#!/usr/bin/env python3
"""USB serial IMU + front camera recorder for BLE-independent baseline."""
import argparse, csv, json, struct, time, zlib
from pathlib import Path

def crc16(b):
    c=0xffff
    for x in b:
        c ^= x
        for _ in range(8): c=(c>>1)^0xa001 if c&1 else c>>1
    return c

