    a=ap.parse_args(); a.output_dir.mkdir(parents=False,exist_ok=False)
    import serial, cv2
    ser=serial.Serial(a.serial_port,a.baud,timeout=.05); cam=cv2.VideoCapture(a.camera_index,cv2.CAP_DSHOW)
